<script module lang="ts">
/**
 * Plain text still arriving, with a steady caret (`design/components/streaming-text.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/streaming-text.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type Snippet } from 'svelte'

import { SlotText, joinSlot } from '@polymorph/svelte'
import styles from '@polymorph/recipes/ai/streaming-text.module.css'
import Skeleton from '../structure/Skeleton.svelte'

export type StreamingTextSize = NonNullable<StreamingTextProps['size']>

export interface StreamingTextProps {
  /**
   * The text received so far, verbatim, with whitespace and line breaks kept as content.
   */
  children: Snippet
  /**
   * The text step (Text's `sm` or `md`), for the same reason Text has two.
   */
  size?: 'sm' | 'md'
  /**
   * Whether more is coming, which shows the caret and sets `aria-busy` on the root.
   */
  streaming?: boolean
}
</script>

<script lang="ts">
let { children, size = 'md', streaming = false }: StreamingTextProps = $props()
const joined = joinSlot(undefined, () => ({ size: size }))
const childrenText = new SlotText(() => children)
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div
    class={styles.root}
    data-size={size}
    data-state={(streaming) ? 'streaming' : undefined}
    data-pending={(streaming && childrenText.current === '') ? '' : undefined}
    aria-busy={(streaming) ? true : undefined}
    data-member="streaming-text"
    >{#if streaming && childrenText.current === ''
      }<Skeleton shape="text" textStep={size} width={9}
    />{:else
      }<p class={styles.text}
        >{@render children?.()
        }{#if streaming}<span class={styles.caret} aria-hidden="true"></span>{/if
      }</p
    >{/if
  }</div
>{/if
}{@render joined.end?.()}
